        suggestWhistleblowing: 'How do I open whistleblowing?',
        suggest2fa: 'How do I enable 2FA?',
        suggestDashboardCohort: 'Why does Overview ask for a company?',
        suggestHrScore: 'What is HR Score?',
        suggestTurnoverRadar: 'How do I use the turnover radar?',
